def get_user_by_email(email=None):
    """
    Return the AuthUser associated to the email, otherwise it will return None.
    If email is not provided, it will pull it from the headers: Authorization

    Exception:
    Along with AuthError, it may
    :param email:
    :return: AuthUser
    """
    if email is None:
        email = request.headers.get('Email')

    if not email:
        return None

    try:
        auth_user = AuthUser.objects.get(email=email)
        return auth_user
    except ObjectDoesNotExist:
        return None


